#[derive(Clone)]
pub(crate) struct ResolvedChain {
    /// Resolved props (may include inherited props).
    props: Vec<Arc<ParsedProp>>,
    /// Inheritance layers, outermost first.
    inheritance: Vec<InheritedLayer>,
    /// Inherited props keyed by name — for notable_inherited population.
    inherited_by_name: FxHashMap<String, Arc<ParsedProp>>,
    /// The notable props of collapsed sources, which are not in `props`.
    notable: Vec<Arc<ParsedProp>>,
    /// Type names that could not be resolved.
    composes: Vec<String>,
    /// Discriminant prop name if this is a discriminated union.
    discriminant_prop: Option<String>,
}

impl ResolvedChain {
    /// The base empty chain. Deliberately not `Default` — every accumulator
    /// site (`resolve_interface_chain`, `resolve_base_as_chain`, ...) that
    /// wants "start empty, then push into" calls this directly instead; the
    /// two *give-up* entry points (`empty_with_compose`, `give_up`) are the
    /// only public-facing "this type contributes nothing" signals. Visible to
    /// `chain`/`alias`/`extends` since they're child modules of `resolver`.
    fn empty() -> Self {
        Self {
            props: Vec::new(),
            inheritance: Vec::new(),
            inherited_by_name: FxHashMap::default(),
            notable: Vec::new(),
            composes: Vec::new(),
            discriminant_prop: None,
        }
    }

    fn empty_with_compose(type_name: String) -> Self {
        Self { composes: vec![type_name], ..Self::empty() }
    }

    /// Give up resolving `type_name` — record it in `composes` (same as
    /// `empty_with_compose`) and, if `diag` is given, push it onto `state`
    /// first. The sanctioned "give up" entry point for every "this type
    /// couldn't be followed further, stop here" path. Replaces the bare
    /// `ResolvedChain::default()` the cycle-detected branch used to return,
    /// which let that one give-up site skip explaining why.
    fn give_up(type_name: String, diag: Option<Diagnostic>, state: &mut ResolveState) -> Self {
        if let Some(d) = diag {
            state.diagnostics.push(d);
        }
        Self::empty_with_compose(type_name)
    }

    /// Merge a parent chain into self — own props already in `self.props` take priority.
    fn merge_parent(&mut self, parent: ResolvedChain) {
        // Collect existing prop names so we can skip duplicates.
        let existing: FxHashSet<String> = self.props.iter().map(|p| p.name.clone()).collect();

        for prop in parent.props {
            if !existing.contains(&prop.name) {
                self.props.push(Arc::clone(&prop));
            }
            // Always populate inherited_by_name so notable lookup works.
            self.inherited_by_name.entry(prop.name.clone()).or_insert(prop);
        }

        // Prepend parent inheritance layers (parent is further up the chain).
        let mut new_inheritance = parent.inheritance;
        new_inheritance.append(&mut self.inheritance);
        self.inheritance = new_inheritance;

        self.composes.extend(parent.composes);
        self.notable.extend(parent.notable);
        for (name, prop) in parent.inherited_by_name {
            self.inherited_by_name.entry(name).or_insert(prop);
        }

        // A discriminated union nested inside an intersection (e.g. `Base & (A | B)`)
        // surfaces its discriminant on the union member's own chain — propagate it
        // up rather than silently dropping it in favor of the fresh, empty chain
        // being merged into.
        if self.discriminant_prop.is_none() {
            self.discriminant_prop = parent.discriminant_prop;
        }
    }

    /// Merge the next member of an intersection into self. Unlike an extended interface's, a prop both declare keeps
    /// both declarations, as TypeScript intersects them.

    // ── Step 2.4: React's attribute interfaces that name no element ──────────
    // `AriaAttributes` and `RefAttributes<T>` are props, read from React's own declaration under the mode: `full` lists
    // them, `curated` keeps the notable ones, `none` leaves them out. `HTMLProps<T>` is the element's HTML layer below.
    if react_types::is_attribute_builtin(type_name_bare) && super::may_be_react_builtin(type_name, consuming_file, ctx)
    {
        let mut chain = ResolvedChain::empty_with_compose(type_name.to_owned());
        let attributes = |full: bool, state: &mut ResolveState| {
            super::html::builtin_attributes(type_name_bare, type_args, full, consuming_file, ctx, state, depth)
        };
        match ctx.builtin_attribute_listing() {
            None => {}
            Some(true) => chain.props = attributes(true, state),
            Some(false) => chain.notable = attributes(false, state),
        }
        return chain;
    }

    // ── Step 2.5: React builtin check (after source and known patterns) ──────
    // Terminal React types (ReactNode, Ref, FC, etc.) that survived both are not
    // prop providers — add to composes and stop.
    // A builtin name bound elsewhere reaches here only when that binding didn't resolve (a re-export of React's type, a
    // package not installed); React's meaning is then a reported guess.
    let element_props = type_name_bare == "HTMLProps" && super::may_be_react_builtin(type_name, consuming_file, ctx);
    if react_types::is_react_builtin(type_name_bare, &ctx.extra_builtins) && !element_props {
        if !ctx.extra_builtins.contains(type_name_bare) && !super::may_be_react_builtin(type_name, consuming_file, ctx)
        {
            state.diagnostics.push(super::builtin_fallback_diagnostic(type_name, consuming_file, ctx));
        }
        return ResolvedChain::empty_with_compose(type_name.to_owned());
    }

    // HTML attribute interfaces (`InputHTMLAttributes`, ...) are terminal in curated mode, like the builtins above: the
    // element's notable attributes come from the inheritance layer, not from expanding the interface.
    if react_types::html_element_for(type_name_bare).is_some()
        || super::declared_by_react(type_name, &canonical_name, consuming_file, ctx)
    {
        // The element's attributes are still the props' (`Omit<HTMLAttributes<HTMLDivElement>, "title">`), so the
        // layer records them for the mode to list; `Omit` and `Pick` narrow it.
        let element = type_args
            .first()
            .and_then(react_types::html_element_from_collected)
            .or_else(|| react_types::html_element_for(type_name_bare))
            .or_else(|| react_types::html_element_from_args(type_args));
        let mut chain = ResolvedChain::empty_with_compose(type_name.to_owned());
        // `HTMLProps<T>` is `AllHTMLAttributes<T>` and `ClassAttributes<T>`: more than the element's own attributes, so
                for key in &omitted {
                    if !layer.omitted.contains(key) {
                        layer.omitted.push(key.clone());
                    }
                }
            }
            chain
        }

        CollectedTypeAlias::Pick { base, keys, file_path } => {
            let expand_all = state.expand_all;
            state.expand_all = expand_all || ctx.can_collapse();
            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
            state.expand_all = expand_all;
            let Some(picked) = resolve_key_set_or_warn("Pick", keys, file_path, mapping, ctx, state, depth) else {
                chain.props.clear();
                return chain;
            };
            let picked_set: FxHashSet<&str> = picked.iter().map(String::as_str).collect();
            chain.props.retain(|p| picked_set.contains(p.name.as_str()));
            chain.notable.retain(|p| picked_set.contains(p.name.as_str()));
            // The base was a `composes` entry with no picked props (React's declarations stay out of the run unless the
            // attributes are `full`, and then a base interface can still list none of them): read them from React.
            let missing: Vec<String> =
                picked.iter().filter(|name| !chain.props.iter().any(|prop| &prop.name == *name)).cloned().collect();
            if !missing.is_empty() {
                chain.props.extend(react_picked_props(base, &missing, file_path, mapping, ctx, state, depth));
            }
            // Only the picked attributes remain: each is read from the element's layer, which then has nothing left to list.
            for name in &picked {
                if chain.props.iter().any(|prop| &prop.name == name) {
                    continue;
                }
                let attribute = chain.inheritance.iter().find_map(|layer| {
                    layer_attribute(layer, name, ctx, state, depth).filter(|_| layer.html_element.is_some())
                });
                if let Some(attribute) = attribute {
                    chain.props.push(ctx.share(attribute));
                }
            }
            chain.inheritance.retain(|layer| layer.html_element.is_none());
            chain
        }

        CollectedTypeAlias::Partial { base, file_path } => {
            let mut chain = resolve_base_as_chain(base, file_path, mapping, ctx, state, depth);
                    "'{}' cannot be used as a component's props base in '{}' — expected an interface, \
                     intersection, union, or inline object type",
                    base.to_raw_string(),
                    file_path
                ),
                file: Some(file_path.to_string()),
                line: None,
                column: None,
                help: Some("Check that this member of the props type resolves to an object-like shape.".into()),
                code: DiagnosticCode::OpaqueType,
                affects: Vec::new(),
            });
            // `composes` (react-docgen's own mechanism for "props come from this type,
            // named instead of flattened") records the raw expression we just diagnosed,
            // instead of vanishing with only a diagnostic to show for it.
            ResolvedChain::empty_with_compose(base.to_raw_string())
        }
    }
}

pub(super) fn react_props_without_ref_alias(args: &[CollectedType], file: &Utf8Path) -> Option<CollectedTypeAlias> {
    Some(CollectedTypeAlias::Omit {
        base: args.first()?.clone(),
        keys: CollectedType::StringLiteral("ref".into()),
        file_path: file.to_owned(),
    })
