fn a_tagged_factory_takes_the_props_type_that_gives_its_tag() {
    let output = run("Styled.tsx", TAGGED);
    assert_eq!(listed(&output, "Badge"), set(&["id", "tone"]));
    assert!(!output.components.contains_key("Plain"));
}

