import json
import sys


def load(path):
    data = json.load(open(path))
    out = {}
    for key, comp in data['components'].items():
        names = sorted(n for sid in comp['props'] for n in data['propSets'][sid])
        out[key] = (comp['filePath'].split('/packages/', 1)[-1], names)
    return out, data


before, bdata = load(sys.argv[1])
after, adata = load(sys.argv[2])
added = sorted(set(after) - set(before))
removed = sorted(set(before) - set(after))
changed = [k for k in before if k in after and before[k] != after[k]]
print('components', len(before), '->', len(after), 'added', len(added), 'removed', len(removed), 'changed', len(changed))
props = 0
for k in added:
    f, names = after[k]
    props += len(names)
    print('  +', f, k.split(' ')[0], len(names), names[:6])
print('props in added components', props)
for k in removed:
    print('  -', before[k][0], k)
for k in changed:
    print('  ~', k)
bd = {json.dumps(x, sort_keys=True) for x in bdata['diagnostics']}
ad = {json.dumps(x, sort_keys=True) for x in adata['diagnostics']}
print('diagnostics', len(bd), '->', len(ad), 'new', len(ad - bd), 'gone', len(bd - ad))
for x in sorted(ad - bd)[:5]:
    print('   new:', x[:300])
for x in sorted(bd - ad)[:5]:
    print('   gone:', x[:300])

